import Image from 'next/image'
import manifest from '@/lib/media/manifest.generated.json'

const { width, height } = manifest.brand.mark

/**
 * The supplied R7 monogram. "ink" (dark R) is for the ivory site; "light" keeps the
 * original white R for dark backgrounds. Both files are generated by `npm run media`.
 */
export function BrandMark({ variant = 'ink', className = '' }: { variant?: 'ink' | 'light'; className?: string }) {
  return (
    <Image
      src={variant === 'ink' ? '/brand/r7-mark.webp' : '/brand/r7-mark-light.webp'}
      alt="R7"
      width={width}
      height={height}
      unoptimized
      className={`w-auto ${className}`}
    />
  )
}
